# Generated by Descant: acceptance tests.
# frozen_string_literal: true

RSpec.describe "Timekeeping write delay hook outside the test environment" do
  # A delay reachable in a built image would let a caller slow every company's entry writes, so the
  # route must not exist unless the test hooks are loaded, even for the service token.
  it "does not draw the write delay hook route in production unless TIMEKEEPING_TEST_HOOKS is 1" do
    app_root = File.expand_path("../../..", __dir__)
    service_token = SecureRandom.hex(32)
    probe = <<~RUBY
      env = Rack::MockRequest.env_for("/internal/v1/test-hooks/writes/delay", method: "POST",
                                      "CONTENT_TYPE" => "application/json",
                                      input: JSON.generate(milliseconds: 400),
                                      "HTTP_AUTHORIZATION" => "Bearer #{service_token}")
      status, = Rails.application.call(env)
      puts [defined?(Timekeeping::TestHooks) ? "loaded" : "absent", status].join(" ")
    RUBY

    boot = lambda do |extra_env|
      env = ENV.to_h.slice("PATH", "HOME", "GEM_HOME", "GEM_PATH", "BUNDLE_PATH", "BUNDLE_APP_CONFIG").merge(
        "RAILS_ENV" => "production",
        Timekeeping::Environment::DATABASE_URL => Timekeeping::Environment.database_url,
        Timekeeping::Environment::TOKEN_PUBLIC_KEY => OpenSSL::PKey::RSA.generate(2048).public_key.to_pem,
        Timekeeping::Environment::SERVICE_TOKEN => service_token,
        Timekeeping::Environment::MONOLITH_REFERENCE_URL => "http://monolith.invalid"
      ).merge(extra_env)
      Open3.capture2e(env, RbConfig.ruby, "bin/rails", "runner", probe, chdir: app_root, unsetenv_others: true)
    end

    unset_output, unset_status = boot.call({})
    zero_output, zero_status = boot.call("TIMEKEEPING_TEST_HOOKS" => "0")

    expect(unset_status).to be_success, unset_output
    expect(zero_status).to be_success, zero_output
    expect(unset_output.lines.last.split).to eq(%w[absent 404])
    expect(zero_output.lines.last.split).to eq(%w[absent 404])
  end
end
